# Teachable Integration
import requests

TEACHABLE_API_KEY = "d7305f38d29fed78fa85652e3a63e154dd8e8829"
TEACHABLE_BASE_URL = "https://your-school.teachable.com"

def get_courses():
    """Get all courses"""
    response = requests.get(
        f"{TEACHABLE_BASE_URL}/api/v1/courses",
        headers={"api_key": TEACHABLE_API_KEY}
    )
    return response.json()

def get_students():
    """Get student list"""
    response = requests.get(
        f"{TEACHABLE_BASE_URL}/api/v1/users",
        headers={"api_key": TEACHABLE_API_KEY}
    )
    return response.json()

def create_course(title, description):
    """Create a new course"""
    response = requests.post(
        f"{TEACHABLE_BASE_URL}/api/v1/courses",
        headers={"api_key": TEACHABLE_API_KEY},
        json={
            "course": {
                "title": title,
                "description": description
            }
        }
    )
    return response.json()
